"use strict";import FormCache from"./modules/form-cache.js";import FormUI from"./modules/form-ui.js";import{setupPlanSelection}from"./modules/plan-selection.js";import initNavigation from"./modules/form-navigation.js";import initValidation from"./modules/form-validation.js";import initSummary from"./modules/form-summary.js";import initSubmission from"./modules/form-submission.js";import initDynamicFields from"./modules/form-dynamic-fields.js";import initCalculations from"./modules/form-calculations.js";import{isExampleDataButtonEnabled}from"./modules/config.js";import initUserSelect from"./modules/form-user-select.js";import initContratacionSummary from"./modules/form-contratacion-summary.js";import initAutosave from"./modules/form-autosave.js";document.addEventListener("DOMContentLoaded",()=>{FormCache.init();FormUI.init();setupPlanSelection();initDynamicFields();initValidation();initNavigation();initSummary();initCalculations();if(isExampleDataButtonEnabled()){import("./modules/form-example-data.js").then(({default:t})=>{"function"==typeof t&&t()}).catch(t=>{console.error("Error cargando el módulo de datos de ejemplo",t)})}initSubmission();initUserSelect(FormCache);initContratacionSummary();initAutosave();});